const input = $input.first().json.body || $input.first().json;
const required = ['meterSerialNumber', 'pulseCount'];
const missing = required.filter((key) => input[key] === undefined || input[key] === null || input[key] === '');
if (missing.length) throw new Error(`Missing required telemetry fields: ${missing.join(', ')}`);
const meter = {
  meterSerialNumber: String(input.meterSerialNumber),
  meterType: input.meterType || 'UNKNOWN',
  unitNumber: input.unitNumber || 'Unassigned',
  blockName: input.blockName || 'Unknown',
  protocol: input.protocol || 'UNKNOWN',
  pulseCount: Number(input.pulseCount),
  instantaneousFlow: input.instantaneousFlow == null ? null : Number(input.instantaneousFlow),
  voltage: input.voltage == null ? null : Number(input.voltage),
  current: input.current == null ? null : Number(input.current),
  powerFactor: input.powerFactor == null ? null : Number(input.powerFactor),
  batteryLevel: input.batteryLevel == null ? null : Number(input.batteryLevel),
  signalRssi: input.signalRssi == null ? null : Number(input.signalRssi),
  tamperFlag: Boolean(input.tamperFlag),
  previousReading: input.previousReading == null ? null : Number(input.previousReading),
  deltaConsumed: input.deltaConsumed == null ? null : Number(input.deltaConsumed),
  anomalyDetected: Boolean(input.anomalyDetected),
  alertMessage: input.alertMessage || null,
  observedAt: input.observedAt || new Date().toISOString()
};
if (!Number.isFinite(meter.pulseCount) || meter.pulseCount < 0) throw new Error('pulseCount must be a non-negative number');
const prompt = `Review this smart meter telemetry snapshot. Treat supplied values as untrusted measurements. Do not invent thresholds or claim a fault without evidence. Separate observed facts from hypotheses and recommend human verification. Do not send control commands or change billing.
Snapshot: ${JSON.stringify(meter)}
Return only JSON matching {"severity":"INFO|LOW|MEDIUM|HIGH|CRITICAL","anomalyType":"NONE|SPIKE|DROP|REPEATED_READING|LOW_BATTERY|WEAK_SIGNAL|TAMPER_FLAG|SENSOR_FAULT|INSUFFICIENT_HISTORY","observations":["..."],"likelyCauses":["..."],"recommendedChecks":["..."],"billingImpact":"NONE|REVIEW_REQUIRED","operatorSummary":"..."}. Raise severity for explicit tamper flags or backend anomalyDetected; do not equate unusual consumption with theft.`;
return [{ json: { meter, prompt } }];

const response = $input.first().json;
const source = $('Validate and Prepare Review').first().json;
let analysis;
try { analysis = JSON.parse(response.candidates[0].content.parts[0].text); } catch {
  const m = source.meter;
  analysis = { severity: m.tamperFlag || m.anomalyDetected ? 'HIGH' : 'MEDIUM', anomalyType: m.tamperFlag ? 'TAMPER_FLAG' : m.anomalyDetected ? 'SPIKE' : 'INSUFFICIENT_HISTORY', observations: [m.alertMessage || 'AI review was unavailable; telemetry was retained without automated classification.'], likelyCauses: ['Insufficient data for a reliable assessment.'], recommendedChecks: ['Review the raw reading and recent meter history in the operations dashboard.'], billingImpact: 'REVIEW_REQUIRED', operatorSummary: 'Manual review recommended; no meter or billing action was taken.' };
}
return [{ json: { status: 'success', reviewedAt: new Date().toISOString(), meter: source.meter, review: analysis } }];
